import { Toaster, type ToastCloseDetail } from '@absoluteui/components/toast';

const toaster = Toaster.create({ position: 'bottom-center', max: 2 });
let restored = false;
const handle = toaster.show({
  message: 'Conversation archived.',
  action: {
    label: 'Undo',
    onAction: () => {
      restored = true;
    },
  },
});
toaster.element.addEventListener('aui-close', (event) => {
  const { id, reason } = (event as CustomEvent<ToastCloseDetail>).detail;
  if (id === handle.id && reason !== 'action' && !restored) {
    // archive is final
  }
});

const upload = toaster.show({ message: 'Uploading report.pdf', duration: 0 });
upload.update({ tone: 'success', message: 'Uploaded report.pdf', duration: 5000 });
